func valueRun(p unsafe.Pointer, c int32) any {
	r := (*distancecalculation.Run)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.ShipmentMoveID)
	case 5:
		if r.Provider == "" {
			return nil
		}
		return r.Provider
	case 6:
		return r.Source
	case 7:
		if r.RequestSummary == nil {
			return nil
		}
		return r.RequestSummary
	case 8:
		if r.ResponseSummary == nil {
			return nil
		}
		return r.ResponseSummary
	case 9:
		return r.Status
	case 10:
		if r.ErrorCode == "" {
			return nil
		}
		return r.ErrorCode
	case 11:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 12:
		return r.LatencyMillis
	case 13:
		return r.CreatedAt
	}
	return nil
}
